606	func selectCloneTarget(cmd *cobra.Command, placements []coreapi.ResolvedPlacement, clusterFlag string) (coreapi.ResolvedPlacement, error) {
607		// Only resolve the home jurisdiction when it can actually narrow the choice:
608		// with 0-1 placements there's nothing to filter (preferHomeJurisdiction would
