622	// selectPlacement resolves which mirror placement a verb should act on. With one
623	// placement it returns it directly. With an explicit clusterSel it picks the
624	// matching one (or errors listing the available hosts). With more than one and no
625	// selector it prompts interactively, failing fast with a p.selector pointer when
626	// there's no terminal.
627	func selectPlacement(cmd *cobra.Command, placements []coreapi.ResolvedPlacement, clusterSel string, p placementPicker) (coreapi.ResolvedPlacement, error) {
628		// Dedupe by cluster host: one placement per cluster is what a caller acts on,
629		// and the same host appearing twice would only confuse the picker. Key on the
630		// case-folded host — DNS is case-insensitive, so a selector value differing
631		// only in case from the API's ClusterHost must still match (the alternative is
632		// a misleading "not mirrored on ..." after a successful lookup + dial).
633		byHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
634		hosts := make([]string, 0, len(placements))
635		for _, p := range placements {
636			key := strings.ToLower(p.ClusterHost)
637			if _, seen := byHost[key]; seen {
638				continue
639			}
640			byHost[key] = p
641			hosts = append(hosts, key)
642		}
643		sort.Strings(hosts)
644	
645		if clusterSel != "" {
646			match, ok := byHost[strings.ToLower(strings.TrimSpace(clusterSel))]
647			if !ok {
648				return coreapi.ResolvedPlacement{}, fmt.Errorf("repo is not mirrored on %q; available: %s", clusterSel, strings.Join(hosts, ", "))
649			}
650			return match, nil
651		}
652	
653		if len(hosts) == 1 {
654			return byHost[hosts[0]], nil
655		}
656	
657		if !interactive.CanPromptInteractively() {
658			return coreapi.ResolvedPlacement{}, fmt.Errorf("repo is mirrored on %d clusters; pass %s to choose one of: %s", len(hosts), p.selector, strings.Join(hosts, ", "))
659		}
