676			// Ctrl+C / cancelled-context abort. Surface that as a SilentError so the
677			// caller stops instead of falling through to act on a zero-value target
678			// (the `entire:///gh/...` empty-host bug) without main.go reprinting the
679			// message handleFormCancellation already wrote; a real form error propagates.
680			if cerr := handleFormCancellation(cmd.ErrOrStderr(), p.action, err); cerr != nil {
